#include <iostream>
#include <string>
#include <algorithm>
bool isPalindrome(std::string s) {
    std::string r = s;
    std::reverse(r.begin(), r.end());
    return s == r;
}
int main() { std::cout << std::boolalpha << isPalindrome("racecar") << std::endl; }

