#include <iostream>
#include <vector>
int main() {
    std::vector<std::vector<int>> matrix = {{1,2},{3,4},{5,6}};
    std::vector<int> flat;
    for (auto& row : matrix) for (int x : row) flat.push_back(x);
    std::cout << "[";
    for (int i = 0; i < (int)flat.size(); i++) std::cout << (i?", ":"") << flat[i];
    std::cout << "]" << std::endl;
}

#include <iostream>
#include <vector>
#include <set>
int main() {
    std::vector<int> items = {1, 2, 2, 3, 3, 4};
    std::set<int> seen;
    std::vector<int> unique_items;
    for (int x : items) if (seen.insert(x).second) unique_items.push_back(x);
    std::cout << "[";
    for (int i = 0; i < (int)unique_items.size(); i++) std::cout << (i?", ":"") << unique_items[i];
    std::cout << "]" << std::endl;
}

