#include <iostream>
#include <vector>
int main() {
    std::vector<int> fibs;
    int a = 0, b = 1;
    for (int i = 0; i < 8; i++) { fibs.push_back(a); int t = a+b; a=b; b=t; }
    std::cout << "[";
    for (int i = 0; i < (int)fibs.size(); i++) std::cout << (i?", ":"") << fibs[i];
    std::cout << "]" << std::endl;
}

#include <iostream>
#include <map>
#include <vector>
#include <string>
int main() {
    std::vector<std::string> words = {"cat","dog","cat","bird","dog","cat"};
    std::map<std::string,int> counts;
    for (auto& w : words) counts[w]++;
    std::cout << "{";
    bool first = true;
    for (auto& p : counts) { std::cout << (first?"":", ") << p.first << ": " << p.second; first=false; }
    std::cout << "}" << std::endl;
}

