#include <iostream>
#include <functional>
std::function<int()> makeCounter() {
    int count = 0;
    return [count]() mutable { return ++count; };
}
int main() {
    auto counter = makeCounter();
    std::cout << counter() << "\n";
    std::cout << counter() << "\n";
}

