#include <iostream>
#include <vector>
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n-i-1; j++)
            if (arr[j] > arr[j+1]) std::swap(arr[j], arr[j+1]);
}
int main() {
    std::vector<int> arr = {64, 34, 25, 12};
    bubbleSort(arr);
    std::cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) std::cout << (i?", ":"") << arr[i];
    std::cout << "]" << std::endl;
}

