#include <iostream>
#include <string>
class Animal {
public:
    std::string name;
    Animal(std::string n) : name(n) {}
    virtual std::string speak() = 0;
};
class Cat : public Animal {
public:
    Cat(std::string n) : Animal(n) {}
    std::string speak() override { return name + " says meow"; }
};
int main() {
    Cat c("Whiskers");
    std::cout << c.speak() << std::endl;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <functional>
int main() {
    std::vector<int> nums = {1, 2, 3, 4, 5};
    int product = std::accumulate(nums.begin(), nums.end(), 1, std::multiplies<int>());
    std::cout << product << std::endl;
}
